/**
 * tool-definitions — Модификация описаний инструментов для LLM
 *
 * Prevention-уровень: агент знает ограничения ДО вызова инструмента.
 * Enforcement-уровень: tool.execute.before проверяет маркер выполнения.
 * STALE-триггер: event-хук считает tool success, каждые 50 -> stale-trigger.
 */

import { type Plugin } from "@opencode-ai/plugin";
import * as fs from "fs";
import * as path from "path";

const HOME = process.env.HOME || "/home/kasiro";
const STALE_COUNTER = path.join(HOME, ".opencode", ".stale-counter");
const STALE_TRIGGER = path.join(HOME, ".opencode", ".stale-trigger");
const STALE_THRESHOLD = 50;

export default (async () => {
  return {
    "tool.definition": async (input, output) => {
      // Prevention: напоминание о CYCLE 4 для КАЖДОГО инструмента
      const cycleNote = "\n\n⚠️ После использования (если задача ВЫПОЛНЕНА): VERIFY → CYCLE 4 LEARN.";

      if (output.description && !output.description.includes("CYCLE 4")) {
        output.description += cycleNote;
      }

      // Для bash — расширенные ограничения
      if (input.toolID === "bash") {
        const restrictions =
          "\n\nДОСТУПНЫЕ КОМАНДЫ:\n"
          + "  fd, rg, bun, bunx — быстрые аналоги find, grep, npm, npx\n"
          + "  ls, cat, echo, pwd, curl, mkdir, rm (осторожно), cp, mv, cd\n"
          + "  head, tail, wc, sort, uniq, tee, xargs, printf, test\n"
          + "  git, docker, doas, chmod, chown\n"
          + "  ps, df, du, free, uname, whoami, id, uptime\n"
          + "  python3, node, nvim\n\n"
          + "ЗАПРЕЩЕНЫ: find (→ fd), grep (→ rg), npm (→ bun), npx (→ bunx), glob (→ fd)";

        output.description =
          "Execute shell commands in a restricted environment."
          + restrictions
          + cycleNote;
      }
    },

    "experimental.chat.system.transform": async (input, output) => {
      const warmRefresh =
        "[WARM REFRESH]\n"
        + "✅ CYCLE 1 на КАЖДОЕ сообщение — нет исключений\n"
        + "✅ RECALL — только при неуверенности\n"
        + "✅ VERIFY → задача выполнена → CYCLE 4 LEARN\n"
        + "✅ CYCLE 4 — только ПОСЛЕ задачи (не на простых вопросах)\n"
        + "[/WARM REFRESH]\n\n";

      if (output.system && !output.system.startsWith("[WARM REFRESH]")) {
        output.system = warmRefresh + output.system;
      }
    },

    "tool.execute.before": async (input, output) => {
      // Enforcement: добавляем маркер проверки в тело команды для bash.
      // Это не блокировка (SDK не позволяет), но маркер нельзя проигнорировать —
      // он становится частью команды.
      if (input.tool === "bash" && output.args) {
        const cmd = output.args.command || "";
        // Не трогаем простые/уже размеченные команды
        if (typeof cmd === "string" && cmd.length > 15 && !cmd.startsWith("#")) {
          output.args.command =
            "#CYCLE4_VERIFY: перед ответом проверь, завершена ли задача\n"
            + cmd;
        }
      }
    },

    "event": async (input) => {
      const event = input.event;
      if (!event || event.type !== "EventSessionNextToolSuccess") return;

      // Читаем текущий счётчик
      let count = 0;
      try {
        const data = fs.readFileSync(STALE_COUNTER, "utf-8").trim();
        count = parseInt(data, 10) || 0;
      } catch {
        // Файла нет — первый запуск
      }

      count++;

      if (count >= STALE_THRESHOLD) {
        // Достигли порога — пишем триггер и сбрасываем счётчик
        try {
          fs.writeFileSync(STALE_TRIGGER, new Date().toISOString(), "utf-8");
          fs.writeFileSync(STALE_COUNTER, "0", "utf-8");
        } catch (e) {
          // Ошибка записи — не критично
        }
      } else {
        try {
          fs.writeFileSync(STALE_COUNTER, String(count), "utf-8");
        } catch {
          // Ошибка записи — не критично
        }
      }
    },
  };
}) satisfies Plugin;
